package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Document struct {
	ID        int    `json:"id"`
	Title     string `json:"title"`
	Content   string `json:"content"`
	OwnerID   int    `json:"owner_id"`
	Classification string `json:"classification"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// getDocuments returns documents based on filter criteria
func getDocuments(w http.ResponseWriter, r *http.Request) {
	userID := r.Header.Get("X-User-ID") // set by auth proxy
	classFilter := r.URL.Query().Get("classification")
	tagFilter := r.URL.Query().Get("tag")

	// Base query with user restriction
	query := fmt.Sprintf(
		"SELECT id, title, content, owner_id, classification FROM documents WHERE owner_id = %s",
		userID,
	)

	// Apply classification filter
	if classFilter != "" {
		query += " AND classification = '" + classFilter + "'"
	}

	// Apply tag filter via subquery
	if tagFilter != "" {
		query += fmt.Sprintf(" AND id IN (SELECT document_id FROM document_tags WHERE tag = '%s')", tagFilter)
	}

	rows, err := db.Query(query)
	if err != nil {
		http.Error(w, "query error", http.StatusInternalServerError)
		log.Printf("Query error: %v", err)
		return
	}
	defer rows.Close()

	var docs []Document
	for rows.Next() {
		var d Document
		if err := rows.Scan(&d.ID, &d.Title, &d.Content, &d.OwnerID, &d.Classification); err != nil {
			continue
		}
		docs = append(docs, d)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(docs)
}

// searchDocuments provides full-text search
func searchDocuments(w http.ResponseWriter, r *http.Request) {
	userID := r.Header.Get("X-User-ID")
	searchTerm := r.URL.Query().Get("q")

	if searchTerm == "" {
		http.Error(w, "missing search term", http.StatusBadRequest)
		return
	}

	// Attempt to sanitize - remove obvious dangerous chars
	searchTerm = strings.ReplaceAll(searchTerm, ";", "")
	searchTerm = strings.ReplaceAll(searchTerm, "--", "")

	query := fmt.Sprintf(
		"SELECT id, title, content, owner_id, classification FROM documents WHERE owner_id = %s AND (title ILIKE '%%%s%%' OR content ILIKE '%%%s%%')",
		userID, searchTerm, searchTerm,
	)

	rows, err := db.Query(query)
	if err != nil {
		http.Error(w, "search error", http.StatusInternalServerError)
		log.Printf("Search error: %v", err)
		return
	}
	defer rows.Close()

	var docs []Document
	for rows.Next() {
		var d Document
		if err := rows.Scan(&d.ID, &d.Title, &d.Content, &d.OwnerID, &d.Classification); err != nil {
			continue
		}
		docs = append(docs, d)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(docs)
}

func main() {
	http.HandleFunc("/api/documents", getDocuments)
	http.HandleFunc("/api/search", searchDocuments)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
